'use strict';

// MODULES //

var tape = require( 'tape' );
var uniform = require( '@stdlib/random/base/uniform' );
var dtypes = require( '@stdlib/ndarray/dtypes' );
var createFactory = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof createFactory, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if the first argument is not a function', function test( t ) {
	var values;
	var idt;
	var odt;
	var i;

	idt = dtypes( 'real_and_generic' );
	odt = dtypes( 'real_floating_point_and_generic' );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return createFactory( value, [ idt, idt ], odt, {
				'output': 'real_floating_point_and_generic'
			}, {
				'order': 'row-major'
			});
		};
	}
});

tape( 'the function throws an error if the first argument does not have a `factory` method', function test( t ) {
	var idt;
	var odt;

	idt = dtypes( 'real_and_generic' );
	odt = dtypes( 'real_floating_point_and_generic' );

	t.throws( badValue, TypeError, 'throws an error' );
	t.end();

	function badValue() {
		function prng() {
			return 0.0;
		}
		return createFactory( prng, [ idt, idt ], odt, {
			'output': 'real_floating_point_and_generic'
		}, {
			'order': 'row-major'
		});
	}
});

