tape( 'the function returns a function', function test( t ) {
	var idt;
	var odt;
	var f;

	idt = dtypes( 'real_and_generic' );
	odt = dtypes( 'real_floating_point_and_generic' );

	f = createFactory( uniform, [ idt, idt ], odt, {
		'output': 'real_floating_point_and_generic'
	}, {
		'order': 'row-major'
	});
	t.strictEqual( typeof f, 'function', 'returns a function' );
	t.end();
});

tape( 'the function returns a function (no options)', function test( t ) {
	var idt;
	var odt;
	var f;

	idt = dtypes( 'real_and_generic' );
	odt = dtypes( 'real_floating_point_and_generic' );

	f = createFactory( uniform, [ idt, idt ], odt, {
		'output': 'real_floating_point_and_generic'
	});
	t.strictEqual( typeof f, 'function', 'returns a function' );
	t.end();
});

tape( 'the returned function returns a function', function test( t ) {
	var factory;
	var idt;
	var odt;
	var f;

	idt = dtypes( 'real_and_generic' );
	odt = dtypes( 'real_floating_point_and_generic' );

	factory = createFactory( uniform, [ idt, idt ], odt, {
		'output': 'real_floating_point_and_generic'
	}, {
		'order': 'row-major'
	});
	f = factory();
	t.strictEqual( typeof f, 'function', 'returns a function' );
	t.end();
});
